ALTER TABLE "credential_access_log" DROP CONSTRAINT "credential_access_log_action_known";--> statement-breakpoint
ALTER TABLE "credential_access_log" DROP CONSTRAINT "credential_access_log_reason_matches";--> statement-breakpoint
ALTER TABLE "credential_access_log" ADD CONSTRAINT "credential_access_log_action_known" CHECK ("credential_access_log"."action" IN ('create', 'rotate', 'revoke', 'bind', 'unbind', 'use', 'reveal'));--> statement-breakpoint
ALTER TABLE "credential_access_log" ADD CONSTRAINT "credential_access_log_reason_matches" CHECK (("credential_access_log"."outcome" = 'done' AND "credential_access_log"."reason" IS NULL) OR ("credential_access_log"."outcome" = 'refused' AND "credential_access_log"."reason" IS NOT NULL AND "credential_access_log"."reason" IN ('not_permitted', 'credential_revoked', 'credential_expired', 'key_rejected', 'key_service_refused', 'key_service_unavailable', 'key_service_not_configured', 'ciphertext_rejected', 'envelope_malformed')));